# pricing.py
from decimal import Decimal, ROUND_HALF_UP

def notional(price: Decimal, qty: int) -> Decimal:
    """Gross notional of a fill, rounded to cents, half up."""
    if qty < 0:
        raise ValueError("quantity must be non-negative")
    return (price * qty).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

# test_pricing.py
import pytest
from decimal import Decimal
from pricing import notional

def test_typical_fill():
    assert notional(Decimal("42.17"), 300) == Decimal("12651.00")

def test_rounding_boundary_half_up():
    assert notional(Decimal("10.125"), 1) == Decimal("10.13")

def test_zero_quantity():
    assert notional(Decimal("42.17"), 0) == Decimal("0.00")

def test_negative_quantity_rejected():
    with pytest.raises(ValueError):
        notional(Decimal("42.17"), -100)

